-- ---- Разделы каталога ----------------------------------------------
--  Раздел ищется по названию: если такой уже есть, второй
--  не заводится, а товары ложатся в существующий.


-- Дрели, шуруповёрты, перфораторы (40 тов.)
SET @cat := (SELECT category_id FROM `oc_category_description`
             WHERE name = 'Дрели, шуруповёрты, перфораторы' AND language_id = @lang LIMIT 1);
INSERT INTO `oc_category` (`image`,`parent_id`,`top`,`column`,`sort_order`,`status`,`date_added`,`date_modified`)
SELECT '', @parent, IF(@parent = 0, 1, 0), 1, 0, 1, NOW(), NOW()
  FROM DUAL WHERE @cat IS NULL;
SET @cat := IFNULL(@cat, LAST_INSERT_ID());
INSERT IGNORE INTO `oc_category_description` (`category_id`,`language_id`,`name`,`description`,`meta_title`,`meta_description`,`meta_keyword`)
VALUES (@cat, @lang, 'Дрели, шуруповёрты, перфораторы', '', 'Дрели, шуруповёрты, перфораторы', '', '');
INSERT IGNORE INTO `oc_category_to_store` (`category_id`,`store_id`) VALUES (@cat, @store);
INSERT IGNORE INTO `oc_category_path` (`category_id`,`path_id`,`level`)
SELECT @cat, p.`path_id`, p.`level` FROM `oc_category_path` p
 WHERE p.`category_id` = @parent;
SET @lvl := (SELECT IFNULL(MAX(`level`) + 1, 0) FROM `oc_category_path`
              WHERE `category_id` = @cat);
INSERT IGNORE INTO `oc_category_path` (`category_id`,`path_id`,`level`) VALUES (@cat, @cat, @lvl);
UPDATE `oc_import_1c` SET `category_id` = @cat WHERE `cat_guid` = '5240cfc2-c0a1-11ee-b034-a8a1590a763d';
SET @kw := (SELECT 1 FROM `oc_seo_url` WHERE `keyword` = 'dreli-shurupoverty-perforatory'
              AND `store_id` = @store AND `language_id` = @lang LIMIT 1);
INSERT INTO `oc_seo_url` (`store_id`,`language_id`,`query`,`keyword`)
SELECT @store, @lang, CONCAT('category_id=', @cat), 'dreli-shurupoverty-perforatory'
  FROM DUAL WHERE @kw IS NULL;

